-- query_capiro_data catalog text: an Objective saved through the Strategy intake
-- is described by its intake answers; its legacy fields are unused, not missing.
BEGIN;
SET LOCAL ROLE capiro_private_projection_owner;
COMMENT ON VIEW meri_private.client_objectives IS '{"description":"Current nondeleted standalone client objectives, including complete stored business fields, saved Strategy intake answers and readiness. Independent of Strategy goals and advocacy history.","grain":"One current nondeleted standalone Objective per canonical id, within its client_id.","primaryKey":["client_id","id"],"relationships":[],"limitations":["Only currently authorized, nonarchived clients and nondeleted Objectives. General covers the current visible client roster; selected-client scope cannot broaden it.","No automatic-context three-item sample or hidden list cap. Explicit SQL filters/limits and output bounds still apply; returned rows do not establish source-universe completeness.","Two Objective shapes exist; readiness_basis says which. strategy_intake Objectives are described by intake_type, intake_goal and intake_target_date, with owner_user_id as their owner; their outcome, government_problem, ask_type and minimum_win are legacy fields that the intake form does not ask for, so they are blank by design. Describe such an Objective by its intake answers and never report the legacy fields as empty, missing or skipped. objective_fields Objectives are described by outcome, government_problem, ask_type, minimum_win and limits, and their intake_* columns are null.","Create-request hashes, revision history, the free-text Meri context and opaque intake owner identifiers from the Strategy intake, and operational plans/ledgers are not exposed. Current Objective version and readiness do not authorize a write."],"freshnessField":"updated_at"}';
COMMENT ON COLUMN meri_private.client_objectives.outcome IS '{"description":"Full stored desired outcome, including an empty draft value. Legacy objective_fields answer: blank by design when readiness_basis is strategy_intake; use intake_goal instead.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.government_problem IS '{"description":"Full stored government problem, including an empty draft value. Legacy objective_fields answer: blank by design when readiness_basis is strategy_intake.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.ask_type IS '{"description":"funding, policy_authority, both, protect_funding or meri_propose; null when unselected. Legacy objective_fields answer: null by design when readiness_basis is strategy_intake; use intake_type instead.","enum":["funding","policy_authority","both","protect_funding","meri_propose"]}';
COMMENT ON COLUMN meri_private.client_objectives.minimum_win IS '{"description":"Full stored minimum win, including an empty draft value. Legacy objective_fields answer: blank by design when readiness_basis is strategy_intake.","nullable":false}';
COMMENT ON COLUMN meri_private.client_objectives.intake_type IS '{"description":"Saved Strategy intake objective type. Labels: appropriations = Appropriations ask, authorization = Authorization, regulatory = Regulatory / policy, coalition = Coalition / positioning, procurement = Contract / procurement, earmark = Grant / earmark, amendment = Amendment. Null when unselected or when readiness_basis is objective_fields.","enum":["appropriations","authorization","regulatory","coalition","procurement","earmark","amendment"]}';
COMMENT ON COLUMN meri_private.client_objectives.intake_goal IS '{"description":"Saved Strategy intake goal statement, exactly as entered (up to 4000 characters); the main description of a strategy_intake Objective. Null when readiness_basis is objective_fields."}';
COMMENT ON COLUMN meri_private.client_objectives.intake_target_date IS '{"description":"Saved Strategy intake target outcome date, optional. Null when not given or when readiness_basis is objective_fields."}';
COMMIT;
